// eslint.config.mjs (Flat Config)
import js from '@eslint/js';
import prettier from 'eslint-config-prettier';

export default [
  js.configs.recommended,
  { rules: { 'no-console': 'warn' } },
  prettier // siempre al final para desactivar reglas de estilo
];

